input.content:
import { cookies } from 'next/headers';
import { headers } from 'next/headers';

export default function UserPreferences() {
  const cookieStore = cookies();
  const theme = cookieStore.get('theme')?.value || 'light';

  const headersList = headers();
  const acceptLanguage = headersList.get('accept-language') || 'en-US,en;q=0.9';

  const preferredLanguage = acceptLanguage.split(',')[0] || 'en-US';

  return (
    <main>
      <h1>User Preferences</h1>
      <div>
        <p>Theme: {theme}</p>
        <p>Preferred Language: {preferredLanguage}</p>
      </div>
    </main>
  );
}

import { cookies, headers } from 'next/headers';

export default async function UserPreferences() {
  const cookieStore = await cookies();
  const theme = cookieStore.get('theme')?.value || 'light';

  const headersList = await headers();
  const acceptLanguage = headersList.get('accept-language') || 'en-US,en;q=0.9';

  const preferredLanguage = acceptLanguage.split(',')[0] || 'en-US';

  return (
    <main>
      <h1>User Preferences</h1>
      <div>
        <p>Theme: {theme}</p>
        <p>Preferred Language: {preferredLanguage}</p>
      </div>
    </main>
  );
}

